# tile candidate test into 2x2 full plus L triominoes, see exact cover
from functools import lru_cache
G=[[0,8,8,0,8,8],[8,8,8,8,8,8],[0,8,8,0,8,0],[0,0,8,8,8,0]]
S={(r,c) for r,row in enumerate(G) for c,x in enumerate(row) if x==8}
placements=[]
for cells in ([(0,0),(0,1),(1,0),(1,1)],):
 for r in range(3):
  for c in range(5):
   p=frozenset((r+dr,c+dc) for dr,dc in cells)
   if p<=S: placements.append(p)
# four orientations of L triomino
for omit in [(0,0),(0,1),(1,0),(1,1)]:
 for r in range(3):
  for c in range(5):
   p=frozenset((r+dr,c+dc) for dr,dc in [(0,0),(0,1),(1,0),(1,1)] if (dr,dc)!=omit)
   if p<=S: placements.append(p)

def solve(rem,chosen=[]):
 if not rem:return chosen
 p0=min(rem)
 for p in placements:
  if p0 in p and p<=rem:
   x=solve(rem-p,chosen+[p])
   if x:return x
 return None
ans=solve(S)
print('cells',len(S),'cover',ans)
if ans:
 for p in ans:print(sorted(p))
